import React, { useEffect, useRef, useState } from "react";

function Generate() {
  const canvasRef = useRef();
  const containerRef = useRef();
  const [imagePaths, setImagePaths] = useState([]);
  const [isFading, setIsFading] = useState(false);
  const [effects, setEffects] = useState({
    grain: 50,
    scanlines: 50,
    aberration: 50,
    glitch: 50,
    pixelate: 50,
    noise: 50,
    brightness: 50,
    contrast: 50,
    saturation: 50,
    edgeIntensity: 50,
    waveAmplitude: 50,
    spiralDensity: 50,
    trailLength: 50,
    rippleIntensity: 50,
    kaleidoscope: 50,
    neon: 50,
    vaporwave: 50,
  });
  const position = useRef({ x: 0, y: 0 });
  const offset = useRef({ x: 0, y: 0 });
  const isDragging = useRef(false);
  const animationRef = useRef();

  useEffect(() => {
    const stored = JSON.parse(localStorage.getItem("selectedImages") || "[]").slice(0, 5);
    if (!stored.length) return;
    setImagePaths(stored);
    generateImage(stored);
    return () => cancelAnimationFrame(animationRef.current);
  }, []);

  const generateGrain = (ctx, width, height, intensity = 300, gamma = 1.4) => {
    const grainData = ctx.getImageData(0, 0, width, height);
    const data = grainData.data;
    const effectIntensity = (effects.grain / 100) * intensity;
    for (let i = 0; i < data.length; i += 4) {
      const noise = Math.floor(Math.random() * effectIntensity) - effectIntensity / 2;
      data[i] = 255 * Math.pow(Math.min(255, Math.max(0, data[i] + noise)) / 255, 1 / gamma);
      data[i + 1] = 255 * Math.pow(Math.min(255, Math.max(0, data[i + 1] + noise)) / 255, 1 / gamma);
      data[i + 2] = 255 * Math.pow(Math.min(255, Math.max(0, data[i + 2] + noise)) / 255, 1 / gamma);
    }
    ctx.putImageData(grainData, 0, 0);
  };

  const applyScanlines = (ctx, width, height, gap = 3, alpha = 0.15) => {
    ctx.save();
    const effectIntensity = (effects.scanlines / 100) * alpha;
    ctx.fillStyle = `rgba(0,0,0,${effectIntensity})`;
    for (let y = 0; y < height; y += gap) {
      ctx.fillRect(0, y, width, 1);
    }
    ctx.restore();
  };

  const applyChromaticAberration = (ctx, width, height, offset = 2) => {
    const imgData = ctx.getImageData(0, 0, width, height);
    const data = imgData.data;
    const copy = new Uint8ClampedArray(data);
    const effectIntensity = Math.round((effects.aberration / 100) * offset);

    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const i = (y * width + x) * 4;

        const redX = Math.min(width - 1, x + effectIntensity);
        const blueX = Math.max(0, x - effectIntensity);

        const redIndex = (y * width + redX) * 4;
        const blueIndex = (y * width + blueX) * 4;

        data[i] = copy[redIndex];           // Red
        data[i + 1] = copy[i + 1];          // Green (original)
        data[i + 2] = copy[blueIndex + 2];  // Blue
        // Alpha unchanged
      }
    }

    ctx.putImageData(imgData, 0, 0);
  };

  const raiseBlackPoint = (ctx, width, height, threshold = 30) => {
    const imgData = ctx.getImageData(0, 0, width, height);
    const data = imgData.data;

    for (let i = 0; i < data.length; i += 4) {
      // Raise each RGB channel if below threshold
      for (let j = 0; j < 3; j++) {
        data[i + j] = Math.max(data[i + j], threshold);
      }
    }

    ctx.putImageData(imgData, 0, 0);
  };


  const applyGlitchEffect = (ctx, width, height, lineHeight = 4, shiftAmount = 10) => {
    const effectIntensity = (effects.glitch / 100) * shiftAmount;
    for (let y = 0; y < height; y += lineHeight * 4) {
      const shift = (Math.random() - 0.5) * effectIntensity;
      const imageData = ctx.getImageData(0, y, width, lineHeight);
      ctx.putImageData(imageData, shift, y);
    }
  };

  const applyPixelate = (canvas, blockSize = 12) => {
    const ctx = canvas.getContext("2d");
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const data = imageData.data;

    for (let y = 0; y < canvas.height; y += blockSize) {
      for (let x = 0; x < canvas.width; x += blockSize) {
        const i = (y * canvas.width + x) * 4;
        const r = data[i];
        const g = data[i + 1];
        const b = data[i + 2];

        for (let dy = 0; dy < blockSize; dy++) {
          for (let dx = 0; dx < blockSize; dx++) {
            const ii = ((y + dy) * canvas.width + (x + dx)) * 4;
            data[ii] = r;
            data[ii + 1] = g;
            data[ii + 2] = b;
          }
        }
      }
    }

    ctx.putImageData(imageData, 0, 0);
    return canvas;
  };

  const thresholdImage = (canvas) => {
    const ctx = canvas.getContext("2d");
    const imageData = ctx.getImageData(0, 0, 1080, 1080);
    const data = imageData.data;

    for (let i = 0; i < data.length; i += 4) {
      const avg = (data[i] + data[i + 1] + data[i + 2]) / 3;
      const val = avg > 128 ? 255 : 0;
      data[i] = data[i + 1] = data[i + 2] = val;
    }

    ctx.putImageData(imageData, 0, 0);
    return canvas;
  };

  const applyNoise = (ctx, width, height, intensity = 50) => {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const effectIntensity = (effects.noise / 100) * intensity;

    for (let i = 0; i < data.length; i += 4) {
      const noise = (Math.random() - 0.5) * effectIntensity;
      data[i] = Math.min(255, Math.max(0, data[i] + noise));
      data[i + 1] = Math.min(255, Math.max(0, data[i + 1] + noise));
      data[i + 2] = Math.min(255, Math.max(0, data[i + 2] + noise));
    }
    ctx.putImageData(imageData, 0, 0);
  };

  const applyColorAdjustments = (ctx, width, height) => {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const brightness = (effects.brightness - 50) / 50 * 100;
    const contrast = (effects.contrast - 50) / 50 * 100;
    const saturation = effects.saturation / 50;

    for (let i = 0; i < data.length; i += 4) {
      // Brightness
      data[i] = Math.min(255, Math.max(0, data[i] + brightness));
      data[i + 1] = Math.min(255, Math.max(0, data[i + 1] + brightness));
      data[i + 2] = Math.min(255, Math.max(0, data[i + 2] + brightness));

      // Contrast
      const factor = (259 * (contrast + 255)) / (255 * (259 - contrast));
      data[i] = factor * (data[i] - 128) + 128;
      data[i + 1] = factor * (data[i + 1] - 128) + 128;
      data[i + 2] = factor * (data[i + 2] - 128) + 128;

      // Saturation
      const gray = 0.2989 * data[i] + 0.5870 * data[i + 1] + 0.1140 * data[i + 2];
      data[i] = gray + (data[i] - gray) * saturation;
      data[i + 1] = gray + (data[i + 1] - gray) * saturation;
      data[i + 2] = gray + (data[i + 2] - gray) * saturation;
    }
    ctx.putImageData(imageData, 0, 0);
  };

  const applyExclusion = (ctx, width, height, images) => {
    const baseImageData = ctx.getImageData(0, 0, width, height);
    const baseData = baseImageData.data;

    images.forEach((img, index) => {
      if (!img) return;
      const tempCanvas = document.createElement('canvas');
      tempCanvas.width = width;
      tempCanvas.height = height;
      const tempCtx = tempCanvas.getContext('2d');
      tempCtx.drawImage(img, 0, 0, width, height);
      const imgData = tempCtx.getImageData(0, 0, width, height);
      const data = imgData.data;

      for (let i = 0; i < data.length; i += 4) {
        baseData[i] = 255 - Math.abs(baseData[i] - data[i]);
        baseData[i + 1] = 255 - Math.abs(baseData[i + 1] - data[i + 1]);
        baseData[i + 2] = 255 - Math.abs(baseData[i + 2] - data[i + 2]);
      }
    });

    ctx.putImageData(baseImageData, 0, 0);
  };

  const applySobelEdgeDetection = (ctx, width, height) => {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const sobelData = new Uint8ClampedArray(data.length);
    const effectIntensity = effects.edgeIntensity / 100;

    const sobelX = [-1, 0, 1, -2, 0, 2, -1, 0, 1];
    const sobelY = [-1, -2, -1, 0, 0, 0, 1, 2, 1];

    for (let y = 1; y < height - 1; y++) {
      for (let x = 1; x < width - 1; x++) {
        let gx = 0, gy = 0;
        let kernelIdx = 0;

        for (let ky = -1; ky <= 1; ky++) {
          for (let kx = -1; kx <= 1; kx++) {
            const pixelIdx = ((y + ky) * width + (x + kx)) * 4;
            const gray = (data[pixelIdx] + data[pixelIdx + 1] + data[pixelIdx + 2]) / 3;
            gx += gray * sobelX[kernelIdx];
            gy += gray * sobelY[kernelIdx];
            kernelIdx++;
          }
        }

        const magnitude = Math.sqrt(gx * gx + gy * gy) * effectIntensity;
        const pixelIdx = (y * width + x) * 4;
        sobelData[pixelIdx] = sobelData[pixelIdx + 1] = sobelData[pixelIdx + 2] = magnitude;
        sobelData[pixelIdx + 3] = 255;
      }
    }

    ctx.putImageData(new ImageData(sobelData, width, height), 0, 0);
  };

  const applyWaveTransform = (ctx, width, height) => {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const tempData = new Uint8ClampedArray(data);
    const amplitude = (effects.waveAmplitude / 100) * 20;

    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const waveX = x + Math.sin(y * 0.05) * amplitude;
        const waveY = y + Math.cos(x * 0.05) * amplitude;

        if (waveX >= 0 && waveX < width && waveY >= 0 && waveY < height) {
          const srcIdx = (y * width + x) * 4;
          const destIdx = (Math.floor(waveY) * width + Math.floor(waveX)) * 4;

          data[destIdx] = tempData[srcIdx];
          data[destIdx + 1] = tempData[srcIdx + 1];
          data[destIdx + 2] = tempData[srcIdx + 2];
          data[destIdx + 3] = tempData[srcIdx + 3];
        }
      }
    }

    ctx.putImageData(imageData, 0, 0);
  };

  const applySpiralTransform = (ctx, width, height) => {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const tempData = new Uint8ClampedArray(data);
    const centerX = width / 2;
    const centerY = height / 2;
    const density = effects.spiralDensity / 100;

    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const dx = x - centerX;
        const dy = y - centerY;
        const angle = Math.atan2(dy, dx);
        const radius = Math.sqrt(dx * dx + dy * dy);

        const spiralX = centerX + radius * Math.cos(angle + radius * density * 0.01);
        const spiralY = centerY + radius * Math.sin(angle + radius * density * 0.01);

        if (spiralX >= 0 && spiralX < width && spiralY >= 0 && spiralY < height) {
          const srcIdx = (y * width + x) * 4;
          const destIdx = (Math.floor(spiralY) * width + Math.floor(spiralX)) * 4;

          data[destIdx] = tempData[srcIdx];
          data[destIdx + 1] = tempData[srcIdx + 1];
          data[destIdx + 2] = tempData[srcIdx + 2];
          data[destIdx + 3] = tempData[srcIdx + 3];
        }
      }
    }

    ctx.putImageData(imageData, 0, 0);
  };

  const applyTrailEffect = (ctx, width, height) => {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const tempData = new Uint8ClampedArray(data);
    const trailLength = Math.floor((effects.trailLength / 100) * 10);

    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const idx = (y * width + x) * 4;
        let r = 0, g = 0, b = 0, a = 0;

        for (let i = 0; i < trailLength; i++) {
          const offset = i * 4;
          const alpha = 1 - (i / trailLength);
          r += tempData[idx + offset] * alpha;
          g += tempData[idx + offset + 1] * alpha;
          b += tempData[idx + offset + 2] * alpha;
          a += tempData[idx + offset + 3] * alpha;
        }

        data[idx] = r / trailLength;
        data[idx + 1] = g / trailLength;
        data[idx + 2] = b / trailLength;
        data[idx + 3] = a / trailLength;
      }
    }

    ctx.putImageData(imageData, 0, 0);
  };

  const applyRippleEffect = (ctx, width, height) => {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const tempData = new Uint8ClampedArray(data);
    const rippleIntensity = effects.rippleIntensity / 100;
    const centerX = width / 2;
    const centerY = height / 2;

    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const dx = x - centerX;
        const dy = y - centerY;
        const distance = Math.sqrt(dx * dx + dy * dy);
        const angle = Math.atan2(dy, dx);

        const rippleX = x + Math.cos(angle) * Math.sin(distance * 0.1) * rippleIntensity * 10;
        const rippleY = y + Math.sin(angle) * Math.sin(distance * 0.1) * rippleIntensity * 10;

        if (rippleX >= 0 && rippleX < width && rippleY >= 0 && rippleY < height) {
          const srcIdx = (y * width + x) * 4;
          const destIdx = (Math.floor(rippleY) * width + Math.floor(rippleX)) * 4;

          data[destIdx] = tempData[srcIdx];
          data[destIdx + 1] = tempData[srcIdx + 1];
          data[destIdx + 2] = tempData[srcIdx + 2];
          data[destIdx + 3] = tempData[srcIdx + 3];
        }
      }
    }

    ctx.putImageData(imageData, 0, 0);
  };

  const applyKaleidoscope = (ctx, width, height) => {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const tempData = new Uint8ClampedArray(data);
    const segments = Math.floor((effects.kaleidoscope / 100) * 12) + 4;
    const centerX = width / 2;
    const centerY = height / 2;

    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const dx = x - centerX;
        const dy = y - centerY;
        const angle = Math.atan2(dy, dx);
        const radius = Math.sqrt(dx * dx + dy * dy);

        const segmentAngle = (2 * Math.PI) / segments;
        const normalizedAngle = Math.floor(angle / segmentAngle) * segmentAngle;

        const newX = centerX + radius * Math.cos(normalizedAngle);
        const newY = centerY + radius * Math.sin(normalizedAngle);

        if (newX >= 0 && newX < width && newY >= 0 && newY < height) {
          const srcIdx = (y * width + x) * 4;
          const destIdx = (Math.floor(newY) * width + Math.floor(newX)) * 4;

          data[destIdx] = tempData[srcIdx];
          data[destIdx + 1] = tempData[srcIdx + 1];
          data[destIdx + 2] = tempData[srcIdx + 2];
          data[destIdx + 3] = tempData[srcIdx + 3];
        }
      }
    }

    ctx.putImageData(imageData, 0, 0);
  };

  const applyNeonEffect = (ctx, width, height) => {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const tempData = new Uint8ClampedArray(data);
    const intensity = effects.neon / 100;

    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const idx = (y * width + x) * 4;
        const r = tempData[idx];
        const g = tempData[idx + 1];
        const b = tempData[idx + 2];

        // Calculate luminance
        const luminance = (r + g + b) / 3;

        // Apply neon glow
        data[idx] = Math.min(255, r + (255 - r) * intensity * (luminance / 255));
        data[idx + 1] = Math.min(255, g + (255 - g) * intensity * (luminance / 255));
        data[idx + 2] = Math.min(255, b + (255 - b) * intensity * (luminance / 255));
      }
    }

    ctx.putImageData(imageData, 0, 0);
  };

  const applyVaporwaveEffect = (ctx, width, height) => {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const intensity = effects.vaporwave / 100;

    for (let i = 0; i < data.length; i += 4) {
      // Increase saturation
      const max = Math.max(data[i], data[i + 1], data[i + 2]);
      const min = Math.min(data[i], data[i + 1], data[i + 2]);
      const delta = max - min;

      if (delta > 0) {
        const saturation = delta / max;
        const newSaturation = saturation + (1 - saturation) * intensity;

        const factor = newSaturation / saturation;
        data[i] = Math.min(255, data[i] * factor);
        data[i + 1] = Math.min(255, data[i + 1] * factor);
        data[i + 2] = Math.min(255, data[i + 2] * factor);
      }

      // Add pink/cyan tint
      data[i] = Math.min(255, data[i] + 20 * intensity);     // Red
      data[i + 1] = Math.min(255, data[i + 1] + 10 * intensity); // Green
      data[i + 2] = Math.min(255, data[i + 2] + 30 * intensity); // Blue
    }

    ctx.putImageData(imageData, 0, 0);
  };

  const generateImage = (imagePaths) => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const loadImage = (src) =>
      new Promise((resolve) => {
        const img = new Image();
        img.crossOrigin = "Anonymous";
        img.onload = () => resolve(img);
        img.src = src;
      });

    Promise.all(imagePaths.map(loadImage)).then((images) => {
      // Step 1: Stack and apply exclusion
      applyExclusion(ctx, canvas.width, canvas.height, images);

      // Step 2: Edge detection
      applySobelEdgeDetection(ctx, canvas.width, canvas.height);

      // Step 3: Wave transform
      applyWaveTransform(ctx, canvas.width, canvas.height);

      // Step 4: Spiral composition
      applySpiralTransform(ctx, canvas.width, canvas.height);

      // Step 5: Trail effect
      applyTrailEffect(ctx, canvas.width, canvas.height);

      // Step 6: Final enhancements
      applyRippleEffect(ctx, canvas.width, canvas.height);
      applyChromaticAberration(ctx, canvas.width, canvas.height);
      raiseBlackPoint(ctx, canvas.width, canvas.height);

      // Additional effects
      if (effects.grain) generateGrain(ctx, canvas.width, canvas.height);
      if (effects.scanlines) applyScanlines(ctx, canvas.width, canvas.height);
      if (effects.glitch) applyGlitchEffect(ctx, canvas.width, canvas.height);
      if (effects.noise) applyNoise(ctx, canvas.width, canvas.height);
      if (effects.pixelate) applyPixelate(canvas, Math.floor((effects.pixelate / 100) * 20));
      if (effects.kaleidoscope) applyKaleidoscope(ctx, canvas.width, canvas.height);
      if (effects.neon) applyNeonEffect(ctx, canvas.width, canvas.height);
      if (effects.vaporwave) applyVaporwaveEffect(ctx, canvas.width, canvas.height);
      applyColorAdjustments(ctx, canvas.width, canvas.height);
    });
  };

  const handleDownload = () => {
    const canvas = canvasRef.current;
    const link = document.createElement("a");
    link.download = "generated.png";
    link.href = canvas.toDataURL("image/png");
    link.click();
  };

  const handleRegenerate = () => {
    setIsFading(true);
    setTimeout(() => {
      generateImage(imagePaths);
      setIsFading(false);
    }, 300);
  };

  const handleEffectChange = (effect, value) => {
    setEffects(prev => ({ ...prev, [effect]: value }));
    generateImage(imagePaths);
  };

  return (
    <div
      ref={containerRef}
      style={{
        width: "100vw",
        height: "100vh",
        overflow: "hidden",
        position: "relative",
        touchAction: "none",
        cursor: isDragging.current ? "grabbing" : "grab",
        background: "#000",
      }}
    >
      {/* Selected Images Preview */}
      <div style={{
        position: "absolute",
        top: 20,
        left: "50%",
        transform: "translateX(-50%)",
        display: "flex",
        gap: "10px",
        zIndex: 10,
        background: "rgba(255,255,255,0.9)",
        padding: "10px",
        borderRadius: "10px",
      }}>
        {imagePaths.map((path, index) => (
          <img
            key={index}
            src={path}
            alt={`Selected ${index + 1}`}
            style={{
              width: "60px",
              height: "60px",
              objectFit: "cover",
              borderRadius: "5px",
              border: "2px solid #333",
            }}
          />
        ))}
      </div>

      {/* Effects Controls */}
      <div style={{
        position: "absolute",
        top: 100,
        left: 20,
        background: "rgba(255,255,255,0.9)",
        padding: "15px",
        borderRadius: "10px",
        zIndex: 10,
        width: "250px",
        maxHeight: "80vh",
        overflowY: "auto",
      }}>
        <h3 style={{ margin: "0 0 15px 0" }}>Effects</h3>
        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Grain: {effects.grain}%</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.grain}
            onChange={(e) => handleEffectChange('grain', parseInt(e.target.value))}
            style={{ width: "100%" }}
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Scanlines: {effects.scanlines}%</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.scanlines}
            onChange={(e) => handleEffectChange('scanlines', parseInt(e.target.value))}
            style={{ width: "100%" }}
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Chromatic Aberration: {effects.aberration}%</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.aberration}
            onChange={(e) => handleEffectChange('aberration', parseInt(e.target.value))}
            style={{ width: "100%" }}
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Glitch: {effects.glitch}%</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.glitch}
            onChange={(e) => handleEffectChange('glitch', parseInt(e.target.value))}
            style={{ width: "100%" }}
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Pixelate: {effects.pixelate}%</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.pixelate}
            onChange={(e) => handleEffectChange('pixelate', parseInt(e.target.value))}
            style={{ width: "100%" }}
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Noise: {effects.noise}%</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.noise}
            onChange={(e) => handleEffectChange('noise', parseInt(e.target.value))}
            style={{ width: "100%" }}
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Brightness: {effects.brightness}%</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.brightness}
            onChange={(e) => handleEffectChange('brightness', parseInt(e.target.value))}
            style={{ width: "100%" }}
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Contrast: {effects.contrast}%</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.contrast}
            onChange={(e) => handleEffectChange('contrast', parseInt(e.target.value))}
            style={{ width: "100%" }}
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Saturation: {effects.saturation}%</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.saturation}
            onChange={(e) => handleEffectChange('saturation', parseInt(e.target.value))}
            style={{ width: "100%" }}
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Edge Intensity: {effects.edgeIntensity}%</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.edgeIntensity}
            onChange={(e) => handleEffectChange('edgeIntensity', parseInt(e.target.value))}
            style={{ width: "100%" }}
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Wave Amplitude: {effects.waveAmplitude}%</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.waveAmplitude}
            onChange={(e) => handleEffectChange('waveAmplitude', parseInt(e.target.value))}
            style={{ width: "100%" }}
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Spiral Density: {effects.spiralDensity}%</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.spiralDensity}
            onChange={(e) => handleEffectChange('spiralDensity', parseInt(e.target.value))}
            style={{ width: "100%" }}
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Trail Length: {effects.trailLength}%</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.trailLength}
            onChange={(e) => handleEffectChange('trailLength', parseInt(e.target.value))}
            style={{ width: "100%" }}
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Ripple Intensity: {effects.rippleIntensity}%</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.rippleIntensity}
            onChange={(e) => handleEffectChange('rippleIntensity', parseInt(e.target.value))}
            style={{ width: "100%" }}
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Kaleidoscope: {effects.kaleidoscope}%</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.kaleidoscope}
            onChange={(e) => handleEffectChange('kaleidoscope', parseInt(e.target.value))}
            style={{ width: "100%" }}
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Neon: {effects.neon}%</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.neon}
            onChange={(e) => handleEffectChange('neon', parseInt(e.target.value))}
            style={{ width: "100%" }}
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Vaporwave: {effects.vaporwave}%</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.vaporwave}
            onChange={(e) => handleEffectChange('vaporwave', parseInt(e.target.value))}
            style={{ width: "100%" }}
          />
        </div>
      </div>

      <canvas
        ref={canvasRef}
        width={1080}
        height={1080}
        style={{
          display: "block",
          margin: "0 auto",
          marginTop: "100px",
          opacity: isFading ? 0.2 : 1,
          transition: "opacity 0.3s ease",
        }}
      />
      <div style={{ position: "fixed", top: 20, right: 20, display: "flex", gap: "12px", zIndex: 10 }}>
        <button
          onClick={handleRegenerate}
          style={{
            padding: "8px 16px",
            backgroundColor: "#FFD666",
            border: "none",
            borderRadius: "8px",
            cursor: "pointer",
            fontWeight: "bold",
          }}
        >
          Regenerate
        </button>
        <button
          onClick={handleDownload}
          style={{
            padding: "8px 16px",
            backgroundColor: "#333",
            color: "#fff",
            border: "none",
            borderRadius: "8px",
            cursor: "pointer",
            fontWeight: "bold",
          }}
        >
          Download
        </button>
      </div>
    </div>
  );
}

export default Generate;
